 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    shapes = []
    # Find the solid 3x3 colored squares that generate full-grid rays.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                shapes.append((r + 1, c + 1, color))
    horizontal = {}
    vertical = {}
    for r, c, color in shapes:
        horizontal.setdefault(r, set()).add(color)
        vertical.setdefault(c, set()).add(color)
    # Extend each square's central row and column across the grid. At crossings
    # of rays with different colors, leave the crossing empty.
    for r, colors in horizontal.items():
        for c in range(w):
            at = set(colors) | vertical.get(c, set())
            out[r][c] = 0 if len(at) > 1 else next(iter(colors))
    for c, colors in vertical.items():
        for r in range(h):
            at = set(colors) | horizontal.get(r, set())
            out[r][c] = 0 if len(at) > 1 else next(iter(colors))
    return out
